clean_output:
input_requirements = read_requirements(input_requirements_filename)

output_requirements = []

for requirement in input_requirements:
    if requirement.startswith('-e'):
        expanded = expand_editable(conf, requirement)
        if expanded:
            output_requirements.append(expanded)
    else:
        output_requirements.append(requirement)

with open(output_requirements_filename, 'w') as f:
    f.write("\n".join(output_requirements))
